from lib import *
S = SS('n14')
steps = [
    step("handleHTTPRequest 开头决定拿哪个字符串去匹配:UseEscapedPath 为真用 URL.EscapedPath(),否则 UseRawPath 为真且 URL.RawPath 非空就用 RawPath,默认用已经解码的 URL.Path。三个开关默认值:UseRawPath=false、UseEscapedPath=false、UnescapePathValues=true。RawPath 并不总有值:/files/a%2Fb 的 Path 是 /files/a/b、RawPath 是 /files/a%2Fb;而 %20、中文、%25、+、%3F 的 RawPath 都是空串(默认编码就是原样),%7E 因为默认会写成 ~ 所以 RawPath 非空。", t=tl(S(1)), mark=lidx(S(1), 'rPath = c.Request.URL.RawPath', 'rPath = c.Request.URL.EscapedPath()', '/files/a%2Fb       URL.Path', '/files/%7Euser'), done=lidx(S(1), '默认:UseRawPath=false', '/files/a%20b       URL.Path', '/files/%E4%B8%AD   URL.Path'), kv=KV([['默认匹配的串', 'URL.Path(已解码)'], ['RawPath', '只有编码和默认写法不同才有值'], ['%2F', 'Path 里变成斜杠,RawPath 里还是 %2F']], ['RawPath'])),
    step("同一个 /files/:name 在 5 种开关下对 6 个请求的结果。默认:/files/a%2Fb → 404(解码成两段),/files/a%20b → \"a b\",%E4%B8%AD → \"中\",a+b → \"a+b\",100%25 → \"100%\"。UseRawPath=true:%2F 那条能匹配,Unescape=true 时 name=\"a/b\",Unescape=false 时 name=\"a%2Fb\"。UseEscapedPath=true 且 Unescape=true 时 /files/a+b 变成了 \"a b\"(加号被当成空格);Unescape=false 时 name 全保持转义形式(\"a%20b\"、\"%E4%B8%AD\"、\"100%25\")。", t=tl(S(2)), mark=lidx(S(2), '默认  ', 'Escaped=true Unescape=true', 'Escaped=true Unescape=false'), done=lidx(S(2), 'Raw=true Unescape=true', 'Raw=true Unescape=false'), kv=KV([['默认', '%2F → 404'], ['UseRawPath', '%2F → name="a/b"(或 "a%2Fb")'], ['UseEscapedPath + Unescape', '+ 变成空格']], ['UseEscapedPath + Unescape'])),
    step("通配符 *p 同理,但注意 UseRawPath 只影响含 %2F 这类“编码后才不同”的路径:UnescapePathValues=false 时,默认配置下 /s/a%2Fb/c 的 p 已经是 \"/a/b/c\";UseRawPath=true 时才是 \"/a%2Fb/c\"。而 %20、中文、%25 在两种设置下结果相同(\"/a b\"、\"/中\"、\"/a%b\"),因为它们的 RawPath 是空串,UseRawPath 对它们不起作用。", t=tl(S(3)), mark=lidx(S(3), '/s/a%2Fb/c', 'UseRawPath=true UnescapePathValues=false'), done=lidx(S(3), 'UseRawPath=false UnescapePathValues=false', '/s/a%20b', '/s/%E4%B8%AD'), kv=KV([['RawPath 为空时', 'UseRawPath 不起作用'], ['%2F', '唯一随开关变化的写法'], ['/s/a%25b', '两种设置都是 "/a%b"']], ['%2F'])),
    step("风险:默认配置下 /dl/..%2F..%2Fetc%2Fpasswd 是 404,因为 %2F 被解码成斜杠,:name 匹配不了多段;UseRawPath=true 时命中,name=\"../../etc/passwd\",filepath.Join(\"/srv/files\", name) 得到 /etc/passwd;%2e%2e%2fsecret 得到 /srv/secret。UseRawPath 让原本到不了 handler 的路径穿越输入直接进了参数值。", t=tl(S(4)), mark=lidx(S(4), 'name="../../etc/passwd"', 'name="../secret"'), done=lidx(S(4), '[默认]', '/dl/report.pdf', '404 page not found'), kv=KV([['默认', '..%2F 变成多段 → 404'], ['UseRawPath=true', 'name="../../etc/passwd"'], ['结论', '参数拼进文件路径之前必须自己清理']], ['结论'])),
]
A = mkartn('n14', 14, 'Gin,UseRawPath,UnescapePathValues,URL编码,路径穿越,Go,真实验证,动画演示',
    '在 Gin v1.12.0 里实测 UseRawPath 与 UnescapePathValues:RawPath 只在编码和默认写法不同(如 %2F)时才有值;5 种开关组合下 /files/:name 对 6 个请求的结果;UseEscapedPath 且 Unescape 时加号变空格;UseRawPath 打开后 ..%2F..%2Fetc%2Fpasswd 直接进入参数值。',
    '路径里有 %2F 的 URL,Gin 默认匹配不了 /files/:name。打开 UseRawPath 能解决,但会带来什么?这篇把三个开关的组合、哪些字符受影响、取到的值长什么样都列出来,并验证打开它之后的路径穿越风险。',
    [('404 → "a/b"', 'UseRawPath=true 且 Unescape=true 时 /files/a%2Fb 的结果(默认是 404)'), ('"a b"', 'UseEscapedPath 且 Unescape 时 /files/a+b 的 name,加号变成了空格'), ('../../etc/passwd', 'UseRawPath=true 时 /dl/..%2F..%2Fetc%2Fpasswd 的 name')],
    [('三个开关与 RawPath', '<p>Gin 默认用已经解码的 <code>URL.Path</code> 去匹配路由,所以 <code>%2F</code> 会变成真的斜杠。<code>URL.RawPath</code> 只有在“默认的编码方式与原始写法不同”时才被 net/url 填上:<code>%2F</code>、<code>%7E</code> 会有,<code>%20</code>、中文、<code>%25</code>、<code>+</code>、<code>%3F</code> 都是空串。所以 <code>UseRawPath</code> 对后面这些写法没有任何作用。</p>'),
     ('5 种组合下的取值', '<p>只有 <code>UseRawPath</code> 或 <code>UseEscapedPath</code> 才能让 <code>%2F</code> 留在同一段里。<code>UnescapePathValues=true</code> 时取出的值再被解码(<code>a%2Fb</code> → <code>a/b</code>),关掉则保持转义形式。一个容易忽略的差别:<code>UseEscapedPath=true</code> 加 Unescape 时用的是 <code>url.QueryUnescape</code>,所以 <code>a+b</code> 会变成 <code>a b</code>——这是查询串的规则,不是路径的规则。</p>'),
     ('通配符里的 %2F', '<p><code>*p</code> 也一样:默认情况 <code>/s/a%2Fb/c</code> 的 p 是 <code>/a/b/c</code>(已经分不清原来有没有编码);只有 <code>UseRawPath=true</code> 且不解码时才能保留 <code>/a%2Fb/c</code>,后面的代码可以自己区分两种斜杠。</p>'),
     ('安全边界', '<p>默认配置里 <code>..%2F</code> 因为被拆成多段,碰巧进不了 <code>:name</code>。打开 <code>UseRawPath</code> 之后,<code>:name</code> 的值是 <code>../../etc/passwd</code>,直接拼进文件路径就是路径穿越。打开这个开关的同时,必须对参数做白名单或 <code>filepath.Base</code> 之类的清理。</p>')],
    steps,
    [ENV_N_GIN + '。请求用 httptest.NewRequest 构造(没有经过真实的 http.Server 与 http.ServeMux);net/url 的 RawPath 行为来自 Go 1.27.1 的标准库;每种情形各一次',
     '没有验证:真实浏览器和 curl 对 %2F 的预处理(许多反向代理会拒绝或改写 %2F,如 nginx 的 merge_slashes、proxy_pass 的处理);UseRawPath 与静态文件服务(Static)的组合;其它特殊字符(分号、反斜杠)在各开关下的表现;Gin 其他版本的行为'],
    'UseRawPath 与转义')
